// Persistence: row-shaped DAO
public sealed class OrderDao { public Guid Id { get; set; } public int TotalCents { get; set; } }

// Repository: mapper lives here
public Order Get(Guid id) {
    var dao = _connection.QuerySingle<OrderDao>("select * from orders where id = @id", new { id });
    return new Order(new OrderId(dao.Id), Money.Cents(dao.TotalCents));
}
